49: <script>
50: /** 房屋用途固定四大类：1 住宅 / 2 商业 / 3 办公用房 / 其他归入其它 */
51: const PURPOSE_COLUMNS = [
52:   { key: '1', label: '住宅' },
53:   { key: '2', label: '商业' },
54:   { key: '3', label: '办公用房' },
55:   { key: '4', label: '其它' }
56: ]
57: 
58: const STATE_NAME_MAP = {
59:   available: '可售',
60:   unsale: '待售(不可售)',
61:   initial: '合同草签',
62:   preRecord: '合同预备案(合同申请)',
63:   record: '合同备案',
64:   retention: '自留',
65:   mortgage: '抵押',
66:   limited: '限制'
67: }
68: 
69: /** 展示名覆盖：合同预备案取括号内的「合同申请」，不展示括号前后全部文字 */
70: const STATE_LABEL_OVERRIDE = {
71:   preRecord: '合同申请'
72: }
73: 
74: /** 状态展示顺序（与业务图例一致） */
75: const STATE_ORDER = ['available', 'retention', 'mortgage', 'limited', 'initial', 'preRecord', 'record', 'unsale']
76: 
77: function normalizePurpose(purpose) {
78:   const key = String(purpose == null ? '' : purpose).trim()
79:   // 兼容两类编码：精简码 1/2/3/4，以及 lpb 字典码 001/016/031/033
80:   if (key === '1' || key === '001') return '1' // 住宅
81:   if (key === '2' || key === '016') return '2' // 商业
82:   if (key === '3' || key === '031') return '3' // 办公用房
83:   return '4' // 其它
84: }
85: 
86: export default {
87:   name: 'LpbStatisticsDialog',
88:   props: {
89:     visible: {
90:       type: Boolean,
91:       default: false
92:     },
93:     projectId: {
94:       type: [String, Number],
95:       default: ''
96:     },
97:     buildingId: {
98:       type: [String, Number],
99:       default: ''
100:     }
101:   },
102:   data() {
103:     return {
104:       loading: false,
105:       rows: [],
106:       purposeColumns: PURPOSE_COLUMNS
107:     }
108:   },
109:   computed: {
110:     dialogVisible: {
111:       get() {
112:         return this.visible
113:       },
114:       set(val) {
115:         this.$emit('update:visible', val)
116:       }
117:     },
118:     tableRows() {
119:       const sorted = [...this.rows].sort((a, b) => {
120:         const ia = STATE_ORDER.indexOf(a.state)
121:         const ib = STATE_ORDER.indexOf(b.state)
122:         return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib)
123:       })
124:       return sorted.map((row) => {
125:         const cellsMap = {}
126:         let totalArea = 0
127:         let totalQty = 0
128:         ;(row.cells || []).forEach((cell) => {
129:           const key = normalizePurpose(cell.purpose)
130:           const area = Number(cell.area) || 0
131:           const qty = Number(cell.qty != null ? cell.qty : cell.count) || 0
132:           if (!cellsMap[key]) cellsMap[key] = { area: 0, qty: 0 }
133:           cellsMap[key].area += area
134:           cellsMap[key].qty += qty
135:           totalArea += area
136:           totalQty += qty
137:         })
138:         return {
139:           state: row.state,
140:           stateName: STATE_LABEL_OVERRIDE[row.state] || row.stateName || STATE_NAME_MAP[row.state] || row.state || '-',
141:           cellsMap,
142:           totalArea,
143:           totalQty
144:         }
145:       })
146:     }
147:   },
148:   watch: {
149:     visible(val) {
150:       if (val) this.load()
151:     }
152:   },
153:   methods: {
154:     load() {
155:       if (!this.projectId || !this.buildingId) return
156:       this.loading = true
157:       this.$post('/building/house/lpbStatistics', { projectId: this.projectId, buildingId: this.buildingId })
158:         .then((res) => {
159:           if (res.code != null && res.code != 200) {
160:             this.msgError(res.msg || '统计失败')
161:             this.rows = []
162:             return
163:           }
164:           this.rows = Array.isArray(res.data) ? res.data : []
165:         })
166:         .catch(() => {
167:           this.msgError('统计失败')
168:           this.rows = []
169:         })
170:         .finally(() => {
171:           this.loading = false
172:         })
173:     },
174:     getCell(row, key) {
175:       return (row && row.cellsMap && row.cellsMap[key]) || { area: 0, qty: 0 }
176:     },
177:     rowClassName({ row }) {
178:       return `stat-row stat-row-${row.state}`
179:     },
180:     formatArea(value) {
181:       const num = Number(value) || 0
182:       return this.formatters.amountFormatter(null, null, num)
183:     },
184:     formatCount(value) {
185:       return Number(value) || 0
186:     }
187:   }
188: }
189: </script>
